(function(root){'use strict';
const maximum=100000000000000n;
function parse(text){if(typeof text!=='string')throw Error('بڕی پارەی ژمێردراو بنووسە.');const normalized=text.trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776));if(!/^\d{1,15}$/.test(normalized)||BigInt(normalized)>maximum)throw Error('بڕەکە دەبێت ژمارەیەکی تەواوی سفر یان زیاتر بێت، تا 100,000,000,000,000 دینار؛ بەبێ کۆما.');return BigInt(normalized).toString();}
function compare(expected,input){if(typeof expected!=='string'||!/^\d{1,30}$/.test(expected))throw Error('باڵانسی ڕاپۆرت نادروستە.');const actual=parse(input),difference=BigInt(actual)-BigInt(expected);return {expected:BigInt(expected).toString(),actual,difference:difference.toString(),status:difference===0n?'balanced':difference>0n?'surplus':'shortage'};}
const labels={balanced:'یەکسانە',surplus:'زیادە',shortage:'کەمە'};
function cell(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
function csv(report,result,countedAt){const verified=compare(report.cash.closing,result.actual);if(verified.difference!==result.difference||verified.expected!==result.expected||verified.status!==result.status||report.timezone!=='Asia/Baghdad'||report.currency!=='IQD'||!/^\d{4}-\d{2}-\d{2}$/.test(report.day)||!Number.isFinite(Date.parse(report.generated_at))||!Number.isFinite(Date.parse(countedAt)))throw Error('بەراورد ئامادە نییە.');return '\ufeff'+[['ڕۆژی ڕاپۆرت','کاتی ئامادەکردنی ڕاپۆرت','کاتی نووسینی ژمارە','کاتی ناوچە','دراو','باڵانسی ڕاپۆرت','پارەی ژمێردراو','جیاوازی — ژمێردراو − ڕاپۆرت','دۆخ','تێبینی'],[report.day,report.generated_at,countedAt,report.timezone,report.currency,result.expected,result.actual,result.difference,labels[result.status],'بەراوردی کاتی؛ هیچ مامەڵە یان داخستنی ڕۆژ تۆمار ناکات.']].map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';}
root.DailyCashCount={parse,compare,labels,csv};if(typeof module==='object'&&module.exports)module.exports=root.DailyCashCount;
})(globalThis);
